CREATE TABLE app_user (id BIGSERIAL PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(16) NOT NULL CHECK (role IN ('USER','ADMIN')), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE refresh_token (id UUID PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_user(id), token_hash VARCHAR(128) NOT NULL, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id BIGSERIAL PRIMARY KEY, actor_id BIGINT REFERENCES app_user(id), action VARCHAR(100) NOT NULL, target_type VARCHAR(100), target_id VARCHAR(100), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
